// The `catalog` tool (design 6.2): on-demand documentation, generated by @glimpse/catalog from the same definitions
// the compiler validates against.
import {
  componentDoc, componentIndex, COMPONENT_BY_NAME, examplesDoc, parseViewRef, SOURCE_BY_NAME, sourceDoc, sourceIndex, VIEW_BY_NAME, VIEW_INDEX, viewDoc,
} from '@glimpse/catalog';
import {loadToolchain} from '../spec/compile.ts';
import {closeMatch, nearest} from '../spec/errors.ts';
import {refSignature} from '../spec/expand.ts';
import type {SourceRegistry} from '../sources/registry.ts';
import {failed, text, type ToolResult} from './result.ts';

export const CATALOG_DESCRIPTION =
  'Look up Glimpse details. names: components ("DataTable"), sources ("git.churn"), presets ("view:diff", returns the preset\'s Express source), "grammar" (full Express reference) or "examples". No names: the index.';

export const CATALOG_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  properties: {names: {type: 'array', items: {type: 'string'}}},
} as const;

const MAX_NAMES = 12;
const GLIMPSE_GRAMMAR_NOTES = [
  'In a Glimpse spec:',
  "- Write only the statements: no <a2ui> tags, no surface(...) line (the id argument of show selects the view).",
  "- Strings may use 'single' or \"double\" quotes; an apostrophe inside a single-quoted string is fine ('doesn't').",
  "- A data argument may be a source ref string ('git.churn src top=20'); it is bound locally and never sent to you.",
  '- Glimpse declares no client functions and no checks: rules 7 and 9 below do not apply.',
].join('\n');

function index(): string {
  return [`Views: ${VIEW_INDEX}`, 'Components (? optional):', componentIndex(), `Sources: ${sourceIndex()}`,
    'catalog{names:[...]} for details: a component, a source, "view:<name>", "grammar" or "examples".'].join('\n');
}

const viewNames = (): string[] => [...VIEW_BY_NAME.keys(), 'gallery'];

/** Every name the tool answers, for fuzzy matching. */
function vocabulary(registry: SourceRegistry | undefined): string[] {
  return [...COMPONENT_BY_NAME.keys(), ...new Set([...SOURCE_BY_NAME.keys(), ...(registry?.keys() ?? [])]), ...viewNames().map(name => `view:${name}`), 'grammar', 'examples'];
}

async function lookup(name: string, registry: SourceRegistry | undefined): Promise<string | undefined> {
  if (name === 'grammar') return `${GLIMPSE_GRAMMAR_NOTES}\n\n${(await loadToolchain()).grammar}`;
  if (name === 'examples') return examplesDoc();
  if (COMPONENT_BY_NAME.has(name)) return componentDoc(name);
  if (SOURCE_BY_NAME.has(name)) return sourceDoc(name);
  const extra = registry?.get(name);
  if (extra) return `${refSignature(extra.meta)} -> ${extra.meta.kind} (${extra.meta.shape}, max ${extra.meta.budget}) - ${extra.meta.doc}`;
  const call = name.startsWith('view:') ? name.slice(5).trim() : viewNames().includes(name.split(/\s+/)[0] ?? '') ? name : undefined;
  if (call !== undefined) {
    const {view, target, args} = parseViewRef(call);
    return viewDoc(view, target, args);
  }
  return undefined;
}

/** `registry` adds sources the catalog does not list (none in production); undefined before the services are loaded. */
export async function catalogTool(args: {names?: unknown}, registry: SourceRegistry | undefined): Promise<ToolResult> {
  const names = Array.isArray(args.names) ? args.names.filter((name): name is string => typeof name === 'string' && name.trim() !== '').map(name => name.trim()) : [];
  if (names.length === 0) return text(index());

  const blocks: string[] = [];
  let found = 0;
  for (const name of [...new Set(names)].slice(0, MAX_NAMES)) {
    let doc = await lookup(name, registry);
    if (doc === undefined) {
      const words = vocabulary(registry);
      // A bare or misspelt name: try the closest catalog name, with and without the view: prefix.
      const guess = closeMatch(name, words) ?? closeMatch(`view:${name}`, words);
      doc = guess ? await lookup(guess, registry) : undefined;
      if (doc !== undefined) doc = `"${name}" -> ${guess}\n${doc}`;
    }
    if (doc === undefined) blocks.push(`unknown "${name.slice(0, 60)}". Nearest: ${nearest(name, vocabulary(registry)).join(' ')}`);
    else { blocks.push(doc); found++; }
  }
  if (names.length > MAX_NAMES) blocks.push(`(${names.length - MAX_NAMES} more names ignored: ask for at most ${MAX_NAMES} at a time)`);
  const body = blocks.join('\n\n');
  return found === 0 ? failed(`${body}\n\n${index()}`) : text(body);
}
